<template><main class="profile-page"><section><h1>完善账号资料</h1><p>首次登录需要先填写账号信息，保存后即可使用平台。</p><el-form label-width="110px"><el-form-item v-for="name in names" :key="name" :label="name"><el-input v-model.trim="fields[name]"/></el-form-item></el-form><el-button type="primary" :loading="saving" @click="save">保存资料</el-button></section></main></template>
<script>import {completeUserProfile} from '@/api/AccountManagement';import {getUserInfo,setUserInfo,landingRoute} from '@/utils/auth';export default{data(){const info=getUserInfo();return{saving:false,fields:{...(info.profileFields||{})}}},computed:{names(){return Object.keys(this.fields)}},methods:{async save(){if(this.names.some(name=>!this.fields[name]))return this.$message.warning('请完整填写账号资料');this.saving=true;try{await completeUserProfile(this.fields);const info={...getUserInfo(),mustCompleteProfile:false,profileFields:this.fields};setUserInfo(info);this.$store.commit('Match/SET_USER_INFO',info);this.$router.replace(landingRoute())}finally{this.saving=false}}}}</script>
<style scoped>.profile-page{min-height:100vh;display:grid;place-items:center;background:#f4f7fb}.profile-page section{width:min(520px,calc(100vw - 32px));padding:32px;background:#fff;border:1px solid #dfe6ef;border-radius:6px}.profile-page h1{margin-top:0}.profile-page p{color:#76849a;margin-bottom:24px}</style>
